<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $d=journeys_input(); if(!journeys_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} if(!journeys_require_active($db,$uid)){ApiResponse::forbidden('Active account required.');exit;} $title=trim((string)($d['title']??'')); $desc=trim((string)($d['description']??'')); if($title===''||mb_strlen($title)>JOURNEY_TITLE_MAX){ApiResponse::validation(['title'=>'Valid title required.']);exit;} if(mb_strlen($desc)>JOURNEY_DESC_MAX){ApiResponse::validation(['description'=>'Description too long.']);exit;} [$start,$end]=journeys_validate_dates(trim((string)($d['start_date']??'')),trim((string)($d['end_date']??''))); $privacy=journeys_clean_privacy((string)($d['privacy_level']??'private')); $status=journeys_clean_status((string)($d['status']??'draft')); $legacy=journeys_legacy_privacy($privacy); $s=$db->prepare('INSERT INTO journeys (owner_id,title,description,start_date,end_date,privacy_level,status) VALUES (:owner,:title,:description,:start_date,:end_date,:privacy,:status)'); $s->execute(['owner'=>$uid,'title'=>$title,'description'=>$desc?:null,'start_date'=>$start,'end_date'=>$end,'privacy'=>$legacy,'status'=>$status]); $id=(int)$db->lastInsertId(); $p=$db->prepare("INSERT INTO journey_participants (journey_id,user_id,role,status,invited_by,responded_at) VALUES (:j,:u,'owner','accepted',:u,NOW())"); $p->execute(['j'=>$id,'u'=>$uid]); ApiResponse::success(['journey'=>journeys_format($db,journeys_find($db,$id))],'Journey created.',201); }catch(Throwable $e){Logger::error('Journey create failed',['error'=>$e->getMessage()]);ApiResponse::serverError($e instanceof InvalidArgumentException?$e->getMessage():'Unable to create journey.');}
?>
